style:
/* 素栏 —— 左侧窄栏放技能与意向，右侧主栏专注履历 */

.tw-sulan.layout-sidebar.resume-paper {
  padding-top: 15mm;
}

.tw-sulan.layout-sidebar.resume-paper .paper-header {
  margin: 0 0 6mm;
  padding: 0 0 4mm;
  background: none;
  border-bottom: 0.25mm solid #dfe3e6;
  color: #262b2e;
  align-items: flex-start;
  gap: 8mm;
}

.tw-sulan.layout-sidebar.resume-paper .paper-photo {
  order: 3;
  width: 26mm;
  height: 34mm;
  border: none;
  border-radius: 0;
  box-shadow: none;
}

.tw-sulan.layout-sidebar.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background: #f2f4f5;
  color: #7c878e;
  font-size: calc(var(--paper-base-size) * 2);
  font-weight: 700;
}

.tw-sulan.layout-sidebar.resume-paper .paper-name {
  color: #1d2225;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.2);
  letter-spacing: 0.06em;
}

.tw-sulan.layout-sidebar.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: #79858c;
  font-size: calc(var(--paper-base-size) * 0.84);
}

.tw-sulan.layout-sidebar.resume-paper .paper-role {
  margin-top: 1.6mm;
  color: #4a555b;
  font-size: calc(var(--paper-base-size) * 0.9);
  font-weight: 400;
}

.tw-sulan.layout-sidebar.resume-paper .paper-contacts {
  margin-top: 3mm;
  color: #3f4a50;
  font-size: calc(var(--paper-base-size) * 0.85);
  gap: 1.2mm 6mm;
}

.tw-sulan.layout-sidebar.resume-paper .paper-contact__label {
  color: #859097;
}

.tw-sulan.layout-sidebar.resume-paper .sidebar-layout {
  grid-template-columns: 54mm minmax(0, 1fr);
  column-gap: 7mm;
}

.tw-sulan.layout-sidebar.resume-paper .sidebar-aside {
  grid-column: 1;
  padding: 0 7mm 0 0;
  background: none;
  border-top: none;
  border-right: 0.25mm solid #e4e8ea;
}

.tw-sulan.layout-sidebar.resume-paper .sidebar-main {
  grid-column: 2;
}

/* 标题：窄栏用小号加线，主栏用大号加粗线 */
.tw-sulan.layout-sidebar.resume-paper .sidebar-aside .paper-section__title {
  display: block;
  margin-bottom: 2.4mm;
  padding: 0 0 1.2mm;
  border: none;
  border-bottom: 0.22mm solid #dfe3e6;
  color: #262b2e;
  font-size: calc(var(--paper-base-size) * 0.96);
  letter-spacing: 0.12em;
}

.tw-sulan.layout-sidebar.resume-paper .sidebar-aside .paper-section__icon {
  display: none;
}

.tw-sulan.layout-sidebar.resume-paper .sidebar-main .paper-section__title {
  display: block;
  margin-bottom: 3mm;
  padding-bottom: 1.4mm;
  border-bottom: 0.35mm solid #262b2e;
  color: #1d2225;
  font-size: calc(var(--paper-base-size) * 1.08);
  letter-spacing: 0.1em;
}

.tw-sulan.layout-sidebar.resume-paper .sidebar-main .paper-section__icon {
  display: none;
}

.tw-sulan.layout-sidebar.resume-paper .paper-section__body {
  color: #33393d;
}

.tw-sulan.layout-sidebar.resume-paper .paper-item-title {
  color: #1d2225;
  font-size: calc(var(--paper-base-size) * 1.02);
}

.tw-sulan.layout-sidebar.resume-paper .paper-item-period {
  color: #7d878d;
  font-size: calc(var(--paper-base-size) * 0.86);
}

.tw-sulan.layout-sidebar.resume-paper .paper-item-sub {
  color: #465056;
}

.tw-sulan.layout-sidebar.resume-paper .paper-rich ul,
.tw-sulan.layout-sidebar.resume-paper .paper-rich ol {
  padding-left: 1.1em;
}

.tw-sulan.layout-sidebar.resume-paper .paper-rich li::marker {
  color: #9aa4aa;
}

/* 窄栏技能：名称与熟练度同一行，进度条在下 */
.tw-sulan.layout-sidebar.resume-paper .sidebar-aside .paper-skills {
  grid-template-columns: minmax(0, 1fr);
  gap: 2mm;
}

.tw-sulan.layout-sidebar.resume-paper .sidebar-aside .paper-skill {
  position: relative;
  display: block;
  padding-bottom: 0;
  border-bottom: none;
}

.tw-sulan.layout-sidebar.resume-paper .sidebar-aside .paper-skill__name {
  display: block;
  font-size: calc(var(--paper-base-size) * 0.88);
  font-weight: 400;
}

.tw-sulan.layout-sidebar.resume-paper .sidebar-aside .paper-skill__dots {
  display: flex;
  gap: 0;
  margin-top: 1mm;
}

.tw-sulan.layout-sidebar.resume-paper .sidebar-aside .paper-skill__dots i {
  width: 100%;
  height: 1.6mm;
  border-radius: 0;
  background: #e8ecee;
}

.tw-sulan.layout-sidebar.resume-paper .sidebar-aside .paper-skill__dots i.filled {
  background: #7d8d99;
}

.tw-sulan.layout-sidebar.resume-paper .sidebar-aside .paper-skill__level {
  position: absolute;
  top: 0;
  right: 0;
  display: inline;
  color: #818d94;
  font-size: calc(var(--paper-base-size) * 0.78);
}

.tw-sulan.layout-sidebar.resume-paper .paper-note__tag {
  color: #1d2225;
  font-weight: 600;
}

.tw-sulan.layout-sidebar.resume-paper .paper-footer {
  border-top: 0.2mm solid #e4e8ea;
  color: #9aa4aa;
}
